import heapq


def _round(numerator, mode):
    if mode == "half_up":
        return (numerator + 5000) // 10000
    return numerator // 10000


def _ledger(data, sequence_first, discounted):
    cutoff = data.get("cutoff", 10**9)
    chosen = {}
    for pos, event in enumerate(data["events"]):
        seq = event.get("sequence", 0)
        if seq > cutoff:
            continue
        event_id = event.get("id", "anonymous:" + str(pos))
        key = ((seq, event.get("revision", 0), pos) if sequence_first
               else (event.get("revision", 0), pos))
        if event_id not in chosen or key > chosen[event_id][0]:
            chosen[event_id] = (key, event)

    balances = dict(data.get("opening", {}))
    mode = data["rounding"]
    for _, event in chosen.values():
        if event.get("void", False):
            continue
        raw = event["price"] * event.get("quantity", 1)
        discount = min(10000, max(0, event.get("discount_bp", 0)))
        net = _round(raw * (10000 - discount), mode)
        base = net if discounted else raw
        tax = _round(base * event.get("tax_bp", 0), mode)
        total = net + tax
        if event.get("kind") == "refund":
            total = -total
        key = event.get("account", "default") + "|" + event.get("currency", "USD")
        balances[key] = balances.get(key, 0) + total
    return {"balances": balances}


def _dependencies(data):
    packages = data["packages"]
    names = sorted(packages, reverse=True)
    features = set(data.get("features", []))
    blocked = data.get("blocked", {})
    pins = data.get("pins", {})
    roots = data["roots"]
    choices = [[None] + [r for r in packages[n]] for n in names]
    best = None
    best_versions = None

    for selection in product(*choices):
        rows = {name: row for name, row in zip(names, selection) if row is not None}
        versions = {name: row["version"] for name, row in rows.items()}
        if any(name not in versions or not lo <= versions[name] <= hi
               for name, (lo, hi) in roots.items()):
            continue
        if any(name in versions and versions[name] != version
               for name, version in pins.items()):
            continue
        if any(version in blocked.get(name, []) for name, version in versions.items()):
            continue

        edges = {}
        valid = True
        for name, row in rows.items():
            deps = [d for d in row.get("deps", [])
                    if not d.get("feature") or d["feature"] in features]
            edges[name] = []
            for dep in deps:
                target = dep["name"]
                if target not in versions or not dep["min"] <= versions[target] <= dep["max"]:
                    valid = False
                    break
                edges[name].append(target)
            if not valid:
                break
        if not valid:
            continue

        reachable = set()
        stack = list(roots)
        while stack:
            name = stack.pop()
            if name in reachable:
                continue
            if name not in rows:
                valid = False
                break
            reachable.add(name)
            stack.extend(edges[name])
        if not valid or reachable != set(rows):
            continue

        done, active = set(), set()
        def visit(name):
            if name in active:
                return False
            if name in done:
                return True
            active.add(name)
            if any(not visit(other) for other in edges[name]):
                return False
            active.remove(name)
            done.add(name)
            return True
        if not all(visit(name) for name in rows):
            continue

        vector = tuple(versions.get(name, -1) for name in names)
        if best is None or vector < best:
            best = vector
            best_versions = versions
    if best is None:
        return {"error": "unsatisfiable"}
    return {"versions": best_versions}


def _jobs(data):
    jobs = data["jobs"]
    k = data["k"]
    blocked = set(data.get("blocked", []))
    mandatory = set(data.get("mandatory", []))
    quotas = data.get("quotas", {})
    best_value = None
    best_ids = None
    for subset in combinations(jobs, k):
        ids = {j["id"] for j in subset}
        if ids & blocked or not mandatory <= ids:
            continue
        counts = {}
        for job in subset:
            counts[job["group"]] = counts.get(job["group"], 0) + 1
        if any(not lo <= counts.get(group, 0) <= hi
               for group, (lo, hi) in quotas.items()):
            continue
        ordered = sorted(subset, key=lambda j: (j["start"], j["end"]))
        if any(a["end"] > b["start"]
               for a, b in zip(ordered, ordered[1:])):
            continue
        value = sum(j["value"] for j in subset)
        selected = sorted(ids)
        if (best_value is None or value > best_value
                or (value == best_value and selected > best_ids)):
            best_value, best_ids = value, selected
    if best_value is None:
        return {"error": "impossible"}
    return {"selected": best_ids, "value": best_value}


def _routes(data):
    required = data.get("required", [])
    bits = {node: 1 << i for i, node in enumerate(required)}
    full = (1 << len(required)) - 1
    initial_mask = bits.get(data["source"], 0)
    start_state = (data["source"], initial_mask, data["coupons"])
    best = {start_state: data["start"]}
    queue = [(data["start"], data["source"], initial_mask, data["coupons"])]
    graph = [[] for _ in range(data["n"])]
    for edge in data["edges"]:
        graph[edge["u"]].append(edge)
    while queue:
        time, node, mask, remaining = heapq.heappop(queue)
        state = (node, mask, remaining)
        if best.get(state) != time:
            continue
        if node == data["target"] and mask == full and remaining == 0:
            return {"arrival": time}
        for edge in graph[node]:
            depart = max(time, edge["open"])
            if depart >= edge["close"]:
                continue
            for spent in (0, 1) if remaining else (0,):
                duration = edge["duration"]
                if spent:
                    duration = max(1, duration - edge.get("discount", 0))
                arrival = depart + duration
                if arrival > data["deadline"]:
                    continue
                nxt = edge["v"]
                newmask = mask | bits.get(nxt, 0)
                newremaining = remaining - spent
                newstate = (nxt, newmask, newremaining)
                if arrival < best.get(newstate, float("inf")):
                    best[newstate] = arrival
                    heapq.heappush(queue, (arrival, nxt, newmask, newremaining))
    return {"arrival": None}


